mapper.select:
SELECT
    t.id,t.site_name,m.order_mode,m.recharge_rate,m.manual_deposit_limit,m.manual_deposited_amt,m.manual_withdrawn_amt,
    m.withdrawal_limit,m.recharge_amt,m.recharge_fee,m.withdraw_amt,m.order_amt,m.order_result_amt,m.order_fee,m.profit_amt
FROM
    s_market_site t
        INNER JOIN s_marketer m ON m.market_site_id = t.id
WHERE m.marketer_id = #{param.marketerId}

    AND t.site_name LIKE concat(#{param.siteName},'%')


    AND t.status = #{param.status}

ORDER BY ${param.sortField} ${param.sortType}
